1	import {
2	  ArrowRight,
3	  ChevronDown,
4	  CircleAlert,
5	  FilePlus2,
6	  FileText,
7	  Film,
8	  FolderSync,
9	  Image as ImageIcon,
10	  Info,
11	  PenLine,
12	  ShieldCheck,
13	  Unlink,
14	} from "lucide-react";
15	import { useEffect, useRef, useState } from "react";
16	import { useTranslations, type Translator } from "@kaipu/i18n";
17	import {
18	  ModalActions,
19	  ModalButton,
20	  ModalIcon,
21	  ModalOverlay,
22	  ModalText,
23	  ModalTitle,
24	} from "@kaipu/ui";
25	import type { ReconcileFinding, ReconcileScanResult } from "@shared/types/library-reconcile";
26	import {
27	  cancelWaiting,
28	  closeReconcileDialog,
29	  setFixing,
30	  fixAll,
31	  openReconcileDialog,
32	  useReconcile,
33	  type ReconcileRun,
34	} from "./reconcile-store";
35	import styles from "./reconcile.module.css";
36	
37	type LibraryT = Translator<"library">;
38	
39	const fileName = (path: string): string => path.split("/").pop() ?? path;
40	
41	const MEDIA_EXT = /\.(mp4|webm|mov|gif|png|jpe?g|webp)$/u;
42	const IMAGE_EXT = /\.(png|jpe?g|webp)$/u;
43	
44	/** A file's name without its media extension: the row icon carries the kind. */
45	const withoutExt = (name: string): string => name.replace(MEDIA_EXT, "");
46	
47	/** One finding as a table row: the file as it is now, and what happens to it. */
48	export interface FindingRow {
49	  /** The file (or record) as it is now. */
50	  now: string;
51	  /** Renames: the new name. */
52	  renamedTo?: string;
53	  /** Everything else: what happens to it, or why it stays. */
54	  note?: string;
55	  icon: "video" | "image" | "record";
56	}
57	
58	function rowIcon(path: string): FindingRow["icon"] {
59	  if (IMAGE_EXT.test(path)) return "image";
60	  return MEDIA_EXT.test(path) ? "video" : "record";
61	}
62	
63	export function describeFinding(finding: ReconcileFinding, t: LibraryT): FindingRow {
64	  const path = finding.path;
65	  const icon = rowIcon(path);
66	  const note = (text: string, now = path): FindingRow => ({ now, note: text, icon });
67	  switch (finding.kind) {
68	    case "stale-auto-title":
69	    case "untitled-legacy":
70	    case "name-mismatch":
71	      return {
72	        now: withoutExt(path),
73	        renamedTo: withoutExt(finding.newName ?? path),
74	        icon,
75	      };
76	    case "missing-sidecar":
77	      return note(t("reconcileAdopt"), withoutExt(path));
78	    case "missing-media": {
79	      const name = finding.title || fileName(path);
80	      return note(
81	        finding.action === "cloud-only" ? t("reconcileCloudOnly") : t("reconcileToOrphans"),
82	        name,
83	      );
84	    }
85	    case "orphan-companion":
86	      return note(t("reconcileOrphanCompanion"));
87	    case "stem-conflict":
88	      return note(t("reconcileStemConflict"));
89	    case "shared-companion":
90	      return note(t("reconcileSharedCompanion"));
91	    case "duplicate-identity":
92	      return note(t("reconcileDuplicateIdentity"));
93	    case "unreadable-record":
94	      return note(t("reconcileUnreadable"));
95	    case "not-recognized":
96	      return note(t("reconcileNotRecognized"));
97	    case "unreadable-orphan-run":
98	      return note(t("reconcileUnreadableOrphanRun"));
99	  }
100	}
101	
102	const ICONS = { video: Film, image: ImageIcon, record: FileText } as const;
103	
104	/**
105	 * The dialog groups findings by what happens to them, so each group can say why once
106	 * instead of repeating a note on every row. Every kind belongs to exactly one group.
107	 */
108	type GroupId = "rename" | "adopt" | "gone" | "listed";
109	
110	const GROUP_OF: Record<ReconcileFinding["kind"], GroupId> = {
111	  "stale-auto-title": "rename",
112	  "untitled-legacy": "rename",
113	  "name-mismatch": "rename",
114	  "missing-sidecar": "adopt",
115	  "missing-media": "gone",
116	  "orphan-companion": "gone",
117	  "stem-conflict": "listed",
118	  "shared-companion": "listed",
119	  "duplicate-identity": "listed",
120	  "unreadable-record": "listed",
121	  "not-recognized": "listed",
122	  "unreadable-orphan-run": "listed",
123	};
124	
125	const GROUPS = [
126	  {
127	    id: "rename",
128	    icon: PenLine,
129	    title: "reconcileGroupRenameTitle",
130	    action: "reconcileGroupRenameAction",
131	    what: "reconcileGroupRenameWhat",
132	  },
133	  {
134	    id: "adopt",
135	    icon: FilePlus2,
136	    title: "reconcileGroupAdoptTitle",
137	    action: "reconcileGroupAdoptAction",
138	    what: "reconcileGroupAdoptWhat",
139	  },
140	  {
141	    id: "gone",
142	    icon: Unlink,
143	    title: "reconcileGroupGoneTitle",
144	    action: "reconcileGroupGoneAction",
145	    what: "reconcileGroupGoneWhat",
146	  },
147	  {
148	    id: "listed",
149	    icon: CircleAlert,
150	    title: "reconcileGroupListedTitle",
151	    action: "reconcileGroupListedAction",
152	    what: "reconcileGroupListedWhat",
153	  },
154	] as const;
155	
156	const TONE_CLASS: Record<GroupId, string | undefined> = {
157	  rename: styles.toneRename,
158	  adopt: styles.toneAdopt,
159	  gone: styles.toneGone,
160	  listed: styles.toneListed,
161	};
162	
163	/** A native checkbox that can also show "some" (a group with unticked files). */
164	function Check({
165	  checked,
166	  partial = false,
167	  label,
168	  onChange,
169	}: {
170	  checked: boolean;
171	  partial?: boolean;
172	  label: string;
173	  onChange: (checked: boolean) => void;
174	}): React.JSX.Element {
175	  const ref = useRef<HTMLInputElement>(null);
176	  useEffect(() => {
177	    if (ref.current) ref.current.indeterminate = partial;
178	  }, [partial]);
179	  return (
180	    <input
181	      ref={ref}
182	      type="checkbox"
183	      className={styles.check}
184	      checked={checked}
185	      aria-label={label}
186	      onChange={(event) => onChange(event.target.checked)}
187	    />
188	  );
189	}
190	
191	function FindingItem({
192	  finding,
193	  selectable,
194	  fixing,
195	  t,
196	}: {
197	  finding: ReconcileFinding;
198	  /** Fixable findings carry a checkbox; listed ones are never touched. */
199	  selectable: boolean;
200	  fixing: boolean;
201	  t: LibraryT;
202	}) {
203	  const row = describeFinding(finding, t);
204	  const Icon = ICONS[row.icon];
205	  const renamed = row.renamedTo !== undefined;
206	  return (
207	    <li
208	      className={`${styles.row} ${selectable ? styles.rowSelectable : ""} ${selectable && !fixing ? styles.rowOff : ""}`}
209	      // The whole row is the target, so a near miss on the 16 px box still toggles it. The
210	      // box's own click already toggled through its onChange.
211	      onClick={
212	        selectable
213	          ? (event) => {
214	              if ((event.target as HTMLElement).closest("input")) return;
215	              // A drag that selected a name to copy it ends in a click too: not a toggle.
216	              if (window.getSelection()?.toString()) return;
217	              setFixing([finding.path], !fixing);
218	            }
219	          : undefined
220	      }
221	    >
222	      {selectable && (
223	        <Check
224	          checked={fixing}
225	          label={
226	            row.renamedTo !== undefined
227	              ? t("reconcileFixRename", { name: row.now, newName: row.renamedTo })
228	              : t("reconcileFixThis", { name: row.now })
229	          }
230	          onChange={(checked) => setFixing([finding.path], checked)}
231	        />
232	      )}
233	      <Icon size={13} strokeWidth={1.8} aria-hidden className={styles.rowIcon} />
234	      <span className={styles.rowNow} title={row.now}>
235	        {row.now}
236	      </span>
237	      {renamed ? (
238	        <>
239	          <ArrowRight
240	            size={12}
241	            strokeWidth={2}
242	            aria-label={t("reconcileRenamedTo")}
243	            className={styles.rowArrow}
244	          />
245	          <span className={styles.rowAfter} title={row.renamedTo}>
246	            {row.renamedTo}
247	          </span>
248	        </>
249	      ) : (
250	        <span className={styles.rowNote} title={row.note}>
251	          {row.note}
252	        </span>
253	      )}
254	    </li>
255	  );
256	}
257	
258	function FindingGroup({
259	  group,
260	  findings,
261	  open,
262	  onToggle,
263	  skipped,
264	  t,
265	}: {
266	  group: (typeof GROUPS)[number];
267	  findings: ReconcileFinding[];
268	  open: boolean;
269	  onToggle: () => void;
270	  skipped: ReadonlySet<string>;
271	  t: LibraryT;
272	}): React.JSX.Element {
273	  const Icon = group.icon;
274	  const selectable = group.id !== "listed";
275	  const off = selectable ? findings.filter((f) => skipped.has(f.path)).length : 0;
276	  const on = findings.length - off;
277	  const bodyId = `reconcile-group-${group.id}`;
278	  return (
279	    <section
280	      className={`${styles.group} ${TONE_CLASS[group.id] ?? ""}`}
281	      data-group={group.id}
282	      data-open={open || undefined}
283	    >
284	      <div className={styles.groupHeader}>
285	        {selectable && (
286	          <Check
287	            checked={on > 0}
288	            partial={on > 0 && off > 0}
289	            label={t("reconcileFixGroup", { group: t(group.title) })}
290	            onChange={(checked) =>
291	              setFixing(
292	                findings.map((f) => f.path),
293	                checked,
294	              )
295	            }
296	          />
297	        )}
298	        <button
299	          type="button"
300	          className={styles.groupToggle}
301	          aria-expanded={open}
302	          aria-controls={bodyId}
303	          onClick={onToggle}
304	        >
305	          <span className={styles.groupIcon} aria-hidden>
306	            <Icon size={16} strokeWidth={1.8} />
307	          </span>
308	          <span className={`${styles.groupText} ${selectable && on === 0 ? styles.groupOff : ""}`}>
309	            <span className={styles.groupTitleLine}>
310	              <span className={styles.groupTitle}>{t(group.title)}</span>
311	              <span className={styles.groupCount}>
312	                {off > 0
313	                  ? t("reconcileGroupCountPartial", { on, count: findings.length })
314	                  : t("reconcileGroupCount", { count: findings.length })}
315	              </span>
316	            </span>
317	            <span className={styles.groupAction}>{t(group.action)}</span>
318	          </span>
319	          <ChevronDown size={14} strokeWidth={2} aria-hidden className={styles.chevron} />
320	        </button>
321	      </div>
322	      {open && (
323	        <div className={styles.groupBody} id={bodyId}>
324	          <p className={styles.groupWhat}>
325	            <Info size={13} strokeWidth={2} aria-hidden className={styles.groupWhatIcon} />
326	            {t(group.what)}
327	          </p>
328	          {/* Every finding gets a row (and its own checkbox): the list scrolls, nothing is cut. */}
329	          <ul className={styles.rows}>
330	            {findings.map((finding) => (
331	              <FindingItem
332	                key={`${finding.kind}:${finding.path}`}
333	                finding={finding}
334	                selectable={selectable}
335	                fixing={!skipped.has(finding.path)}
336	                t={t}
337	              />
338	            ))}
339	          </ul>
340	        </div>
341	      )}
342	    </section>
343	  );
344	}
345	
346	function Findings({
347	  findings,
348	  skipped,
349	  t,
350	}: {
351	  findings: ReconcileFinding[];
352	  skipped: ReadonlySet<string>;
353	  t: LibraryT;
354	}): React.JSX.Element {
355	  const byGroup = new Map<GroupId, ReconcileFinding[]>();
356	  for (const finding of findings) {
357	    const id = GROUP_OF[finding.kind];
358	    const bucket = byGroup.get(id);
359	    if (bucket) bucket.push(finding);
360	    else byGroup.set(id, [finding]);
361	  }
362	  const present = GROUPS.filter((group) => byGroup.has(group.id));
363	  // One group open at a time, so a long one never pushes the others out of the dialog.
364	  const [openId, setOpenId] = useState<GroupId | null>(present[0]?.id ?? null);
365	  return (
366	    <div className={styles.findings}>
367	      {present.map((group) => (
368	        <FindingGroup
369	          key={group.id}
370	          group={group}
371	          findings={byGroup.get(group.id)!}
372	          open={openId === group.id}
373	          onToggle={() => setOpenId(openId === group.id ? null : group.id)}
374	          skipped={skipped}
375	          t={t}
376	        />
377	      ))}
378	    </div>
379	  );
380	}
381	
382	function SafetyNote({ t }: { t: LibraryT }): React.JSX.Element {
383	  return (
384	    <p className={styles.safety}>
385	      <ShieldCheck size={15} strokeWidth={1.9} aria-hidden className={styles.safetyIcon} />
386	      <span>
387	        <strong>{t("reconcileSafeTitle")}</strong> {t("reconcileSafeBody")}
388	      </span>
389	    </p>
390	  );
391	}
392	
393	function ScanBody({
394	  scan,
395	  skipped,
396	  t,
397	}: {
398	  scan: ReconcileScanResult | null;
399	  skipped: ReadonlySet<string>;
400	  t: LibraryT;
401	}): React.JSX.Element {
402	  if (!scan) return <ModalText>{t("reconcileScanning")}</ModalText>;
403	  switch (scan.status) {
404	    case "busy":
405	      return (
406	        <ModalText>
407	          {t(scan.activity === "export" ? "reconcileBusyExport" : "reconcileBusyRecording")}
408	        </ModalText>
409	      );
410	    case "maintenance":
411	      return <ModalText>{t("reconcileAlreadyRunning")}</ModalText>;
412	    case "error":
413	      return <ModalText>{t("reconcileScanError", { message: scan.message })}</ModalText>;
414	    case "ok":
415	      if (scan.findings.length === 0) {
416	        return <ModalText>{t("reconcileEverythingMatches")}</ModalText>;
417	      }
418	      return (
419	        <>
420	          <SafetyNote t={t} />
421	          <Findings findings={scan.findings} skipped={skipped} t={t} />
422	        </>
423	      );
424	  }
425	}
426	
427	const ACTIVITY_KEYS = {
428	  library: "reconcileActivity_library",
429	  editor: "reconcileActivity_editor",
430	  screenshot: "reconcileActivity_screenshot",
431	  recovery: "reconcileActivity_recovery",
432	  folder: "reconcileActivity_folder",
433	} as const;
434	
435	function RunBody({ run, t }: { run: Exclude<ReconcileRun, { phase: "idle" }>; t: LibraryT }) {
436	  if (run.phase === "waiting") {
437	    const what = run.waitingFor
438	      .map((kind) => ACTIVITY_KEYS[kind as keyof typeof ACTIVITY_KEYS])
439	      .filter(Boolean)
440	      .map((key) => t(key));
441	    return (
442	      <ModalText>
443	        {what.length > 0
444	          ? t("reconcileWaiting", { what: what.join(", ") })
445	          : t("reconcileWaitingSomething")}
446	      </ModalText>
447	    );
448	  }
449	  if (run.phase === "fixing") {
450	    return (
451	      <div className={styles.progress}>
452	        <div className={styles.progressLine}>
453	          <span>{t("reconcileFixing", { done: run.done, total: run.total })}</span>
454	          <span className={styles.progressPercent} aria-hidden>
455	            {Math.round((run.done / Math.max(run.total, 1)) * 100)}%
456	          </span>
457	        </div>
458	        <progress max={Math.max(run.total, 1)} value={run.done} className={styles.bar} />
459	      </div>
460	    );
461	  }
462	  const { result } = run;
463	  switch (result.status) {
464	    case "busy":
465	      return (
466	        <ModalText>
467	          {t(result.activity === "export" ? "reconcileBusyExport" : "reconcileBusyRecording")}
468	        </ModalText>
469	      );
470	    case "already-running":
471	      return <ModalText>{t("reconcileAlreadyRunning")}</ModalText>;
472	    case "error":
473	      return <ModalText>{t("reconcileError", { message: result.message })}</ModalText>;
474	    case "cancelled":
475	      return null;
476	    case "done": {
477	      const { report } = result;
478	      const tiles = [
479	        {
480	          key: "fixed",
481	          label: t("reconcileTileFixed"),
482	          value: report.fixed,
483	          tone: styles.toneAdopt,
484	        },
485	        {
486	          key: "moved",
487	          label: t("reconcileTileMoved"),
488	          value: report.movedToOrphans,
489	          tone: styles.toneGone,
490	        },
491	        {
492	          key: "kept",
493	          label: t("reconcileTileKept"),
494	          value: report.kept.length,
495	          tone: styles.toneListed,
496	        },
497	        {
498	          key: "failed",
499	          label: t("reconcileTileFailed"),
500	          value: report.failed.length,
501	          tone: styles.toneFailed,
502	        },
503	      ].filter((tile) => tile.key === "fixed" || tile.key === "moved" || tile.value > 0);
504	      return (
505	        <div className={styles.report}>
506	          <ModalText>
507	            {t("reconcileDone", { fixed: report.fixed, moved: report.movedToOrphans })}
508	          </ModalText>
509	          <ul className={styles.tiles} aria-hidden>
510	            {tiles.map((tile) => (
511	              <li key={tile.key} className={`${styles.tile} ${tile.tone ?? ""}`}>
512	                <span className={styles.tileValue}>{tile.value}</span>
513	                <span className={styles.tileLabel}>{tile.label}</span>
514	              </li>
515	            ))}
516	          </ul>
517	          {report.kept.length > 0 && (
518	            <ModalText>{t("reconcileKept", { count: report.kept.length })}</ModalText>
519	          )}
520	          {report.failed.length > 0 && (
521	            <ModalText>{t("reconcileFailed", { count: report.failed.length })}</ModalText>
522	          )}
523	        </div>
524	      );
525	    }
526	  }
527	}
528	
529	/** The "Check and fix files" dialog, mounted once in the app shell. */
530	export function ReconcileDialogHost(): React.JSX.Element | null {
531	  const t = useTranslations("library");
532	  const { dialogOpen, scan, scanning, run, skipped } = useReconcile();
533	  if (!dialogOpen) return null;
534	  const fixing = run.phase === "fixing";
535	  const canFix =
536	    run.phase === "idle" && !scanning && scan?.status === "ok" && scan.fixableCount > 0;
537	  const listShown =
538	    run.phase === "idle" && !scanning && scan?.status === "ok" && scan.findings.length > 0;
539	  const selected = canFix
540	    ? scan.findings.filter((f) => f.fixable && !skipped.has(f.path)).length
541	    : 0;
542	  return (
543	    // Non-dismissible only while files are being fixed.
544	    <ModalOverlay
545	      onCancel={fixing ? () => {} : closeReconcileDialog}
546	      labelledBy="reconcile-dialog-title"
547	      size="wide"
548	    >
549	      <div className={styles.sheet}>
550	        {/* Icon beside the title, as in the design: the list gets the height instead. */}
551	        <header className={styles.header}>
552	          <ModalIcon tone="accent">
553	            <FolderSync size={20} strokeWidth={1.8} />
554	          </ModalIcon>
555	          <div className={styles.headerText}>
556	            <ModalTitle id="reconcile-dialog-title">{t("reconcileTitle")}</ModalTitle>
557	            {/* The intro describes a finished scan, so it only shows above an actual list. */}
558	            {listShown && (
559	              <p className={styles.intro}>
560	                {t(scan.fixableCount > 0 ? "reconcileIntro" : "reconcileIntroListedOnly")}
561	              </p>
562	            )}
563	          </div>
564	        </header>
565	        <div className={styles.body}>
566	          {run.phase === "idle" ? (
567	            <ScanBody scan={scanning ? null : scan} skipped={skipped} t={t} />
568	          ) : (
569	            <RunBody run={run} t={t} />
570	          )}
571	        </div>
572	        {canFix && (
573	          <p className={styles.summary}>
574	            {selected === scan.fixableCount
575	              ? t("reconcileSummary", {
576	                  fixable: scan.fixableCount,
577	                  listed: scan.findings.length - scan.fixableCount,
578	                })
579	              : t("reconcileSummarySelected", {
580	                  selected,
581	                  fixable: scan.fixableCount,
582	                  untouched: scan.findings.length - selected,
583	                })}
584	          </p>
585	        )}
586	        <ModalActions>
587	          {run.phase === "waiting" && (
588	            <ModalButton variant="ghost" onClick={cancelWaiting}>
589	              {t("reconcileCancel")}
590	            </ModalButton>
591	          )}
592	          {run.phase === "finished" && (
593	            // "Check again": back to the list, freshly scanned.
594	            <ModalButton variant="ghost" onClick={openReconcileDialog}>
595	              {t("reconcileCheckAgain")}
596	            </ModalButton>
597	          )}
598	          {!fixing && (
599	            <ModalButton variant="ghost" onClick={closeReconcileDialog}>
600	              {t("reconcileClose")}
601	            </ModalButton>
602	          )}
603	          {canFix && (
604	            <ModalButton variant="primary" disabled={selected === 0} onClick={() => void fixAll()}>
605	              {selected === scan.fixableCount
606	                ? t("reconcileFixAll")
607	                : t("reconcileFixSelected", { count: selected })}
